-- Private H N-12. Persistent space property, separate from optional active effect.
create or replace function ml_private.p3h_small(s jsonb,a integer) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(a between 0 and 3 and s->>'version'='web-v0.1.19' and s#>>array['players',a::text,'character']='character-041',false)$$;
create or replace function ml_private.p3h_blocks(s jsonb,a integer,b integer) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select not ml_private.p3h_small(s,a) and not ml_private.p3h_small(s,b)$$;
create or replace function ml_private.p3h_small_allowed(s jsonb,a integer,t integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.p3h_small(s,a) and ml_private.stage4_on_board(s,a) and ml_private.stage4_on_board(s,t) and a<>t and ml_private.p3h_active_allowed(s,a) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),t,s#>>array['players',t::text,'character'])$$;
create or replace function ml_private.p3h_small_crossed(s jsonb,a integer,origin text,destination text,walking boolean default false,root text default null) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare cells jsonb:=jsonb_build_array(destination);startc jsonb:=ml_private.game_data(s,'map')->origin;endc jsonb:=ml_private.game_data(s,'map')->destination;dr integer;dc integer;i integer;cell text;t integer;k text;jobs jsonb:='[]';begin
 if not ml_private.p3h_small(s,a) or origin=destination then return s||jsonb_build_object('_hSmallTasks',jobs);end if;root:=coalesce(root,ml_private.p3e_root(s));
 if walking and (startc->'row'=endc->'row' or startc->'col'=endc->'col') then cells:='[]';dr:=sign((endc->>'row')::int-(startc->>'row')::int);dc:=sign((endc->>'col')::int-(startc->>'col')::int);for i in 1..ml_private.distance_for_version(s->>'version',origin,destination) loop cells:=cells||jsonb_build_array('r'||((startc->>'row')::int+dr*i)||'c'||((startc->>'col')::int+dc*i));end loop;end if;
 s:=jsonb_set(s,'{stage3,h,smallSeen}',coalesce(s#>'{stage3,h,smallSeen}','{}'));
 for cell in select v#>>'{}' from ml_private.arr(cells) v loop for t in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop k:=root||':'||a||':'||t;if t=a or not ml_private.stage4_on_board(s,t) or s#>>array['players',t::text,'cell']<>cell or s#>>array['stage3','h','smallSeen',k]='true' then continue;end if;s:=jsonb_set(s,array['stage3','h','smallSeen',k],'true');jobs:=jobs||jsonb_build_array(ml_private.stage3_task('h-small',jsonb_build_object('actor',a,'target',t,'data',jsonb_build_object('root',root))));end loop;end loop;return s||jsonb_build_object('_hSmallTasks',jobs);end $$;
create or replace function ml_private.p3h_small_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;target integer:=(t->>'target')::int;begin
 if not ml_private.p3h_enabled(s) or t->>'action'<>'h-small' then return s||jsonb_build_object('_hHandled',false);end if;if ml_private.p3h_small_allowed(s,a,target) then s:=ml_private.select_choice(s,'h-small',a,at,jsonb_build_object('source',target,'data',t->'data'));end if;return s||jsonb_build_object('_hHandled',true);end $$;
create or replace function ml_private.p3h_small_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;t integer:=(c->>'source')::int;rolln integer;n integer;idx integer;cards jsonb;card text;taken integer:=0;begin
 if not ml_private.p3h_enabled(s) or c->>'kind'<>'h-small' then return s||jsonb_build_object('_hHandled',false);end if;
 if not timeout and cmd->>'accept'='true' and ml_private.p3h_small_allowed(s,a,t) then s:=ml_private.p3g_owned_die(s,'小',a);rolln:=(s->>'_roll')::int;s:=s-'_roll';if rolln<=3 then s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('source',a,'target',t,'amount',1,'category','response')));s:=ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';else for n in 1..2 loop cards:=s#>array['players',t::text,'hand'];exit when jsonb_array_length(cards)=0;s:=ml_private.int(s,jsonb_array_length(cards));idx:=(s->>'_int')::int;s:=s-'_int';card:=cards->>idx;s:=jsonb_set(s,array['players',t::text,'hand'],cards-idx);s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(card));taken:=taken+1;end loop;s:=ml_private.emit(s,'transfer','S'||(a+1)||' 小：从S'||(t+1)||'随机拿'||taken||'张');end if;end if;return s||jsonb_build_object('_hHandled',true);end $$;
